<div class="hero"><h1>🏪 插件列表</h1><p>选择插件开始使用</p></div>
<div id="marketList"><div class="loading"><div class="spinner"></div>加载中...</div></div>
<script>
fetch('api/index.php?source=market_list').then(r=>r.json()).then(function(d){var el=document.getElementById('marketList');if(!d.success||!d.data.length){el.innerHTML='<div style="text-align:center;padding:40px;color:#aaa">暂无插件</div>';return}el.innerHTML='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px">'+d.data.map(function(p){var click=p.url?'window.location.href=\''+p.url+'\'':'';return '<div style="background:#fff;border:1px solid #e8ecf1;border-radius:12px;padding:24px;cursor:'+(p.url?'pointer':'default')+';transition:all .15s" '+(p.url?'onclick="'+click+'"':'')+' onmouseover="this.style.borderColor=\'#4f6af5\';this.style.boxShadow=\'0 4px 20px rgba(79,106,245,.1)\'" onmouseout="this.style.borderColor=\'#e8ecf1\';this.style.boxShadow=\'none\'"><div style="font-size:36px;margin-bottom:10px">'+p.icon+'</div><div style="font-size:16px;font-weight:700;color:#333">'+esc(p.name)+'</div><div style="font-size:13px;color:#888;margin-top:6px;line-height:1.6">'+esc(p.desc)+'</div><div style="margin-top:12px">'+(p.url?'<span style="display:inline-flex;align-items:center;gap:4px;padding:4px 12px;background:#4f6af5;color:#fff;border-radius:6px;font-size:12px;font-weight:600">▶ 打开</span>':'<span style="display:inline-block;padding:4px 12px;background:#e8f5e9;color:#16a34a;border-radius:6px;font-size:12px;font-weight:600">✓ 已集成</span>')+'</div></div>'}).join('')+'</div>'})
</script>
